package com.johnny.hotel.workforce;
import com.johnny.hotel.entity.SysAuditLog;import com.johnny.hotel.exception.BusinessException;import com.johnny.hotel.mapper.SysAuditLogMapper;import com.johnny.hotel.pagination.*;import com.johnny.hotel.workforce.WorkforceModels.*;import lombok.RequiredArgsConstructor;import org.springframework.dao.DuplicateKeyException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.math.*;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor public class LeaveService {
 private final WorkforceMapper mapper;private final WorkforceAccess access;private final WorkforceApprovalRouting routing;private final WorkforceTaskService workflows;private final SysAuditLogMapper audits;private final PaginationSupport pagination;private final Clock clock;
 private LocalDateTime now(){return LocalDateTime.now(clock);}private void need(boolean ok,String m){if(!ok)throw new BusinessException(409,m);}private String text(String v,String n,int max){if(v==null||v.isBlank())throw new BusinessException(n+" is required");v=v.trim();if(v.length()>max)throw new BusinessException(n+" is too long");return v;}
 private void audit(Long actor,Long target,String action,String detail){need(audits.insert(SysAuditLog.builder().operatorId(actor).targetUserId(target).action(action).detail(detail).build())==1,"Audit write failed");}
 private void history(Long id,String action,Long actor,String detail){need(mapper.leaveHistory(id,action,actor,detail)==1,"Leave history write failed");}
 private void validate(LeaveRequest r,LeaveType t){need(r.getStartAt()!=null&&r.getEndAt()!=null&&r.getStartAt().isBefore(r.getEndAt()),"Leave interval is invalid");need(r.getRequestedAmount()!=null&&r.getRequestedAmount().signum()>0&&r.getRequestedAmount().scale()<=2,"Requested amount is invalid");need(t!=null&&Integer.valueOf(1).equals(t.getActive()),"Leave type is inactive");need(r.getReason()!=null&&!r.getReason().isBlank(),"Reason is required");if(Integer.valueOf(1).equals(t.getRequiresAttachment()))need(r.getAttachmentReference()!=null&&!r.getAttachmentReference().isBlank(),"Attachment is required");BigDecimal n=r.getRequestedAmount().stripTrailingZeros();if("DAY".equals(t.getUnit()))need(n.scale()<=0,"DAY leave amount must be whole days");if("HALF_DAY".equals(t.getUnit()))need(r.getRequestedAmount().multiply(BigDecimal.valueOf(2)).stripTrailingZeros().scale()<=0,"HALF_DAY leave amount must use half-day increments");need(Set.of("DAY","HALF_DAY","HOUR").contains(t.getUnit()),"Unsupported leave unit");}
 @Transactional public LeaveType writeType(Long id,WorkforceRequests.LeaveTypeWrite r){var a=access.actor();access.hrOrSystem(a);need(r!=null,"Request required");var t=LeaveType.builder().id(id).code(text(r.getCode(),"code",40).toUpperCase(Locale.ROOT)).name(text(r.getName(),"name",100)).unit(text(r.getUnit(),"unit",16).toUpperCase(Locale.ROOT)).paidTreatment(text(r.getPaidTreatment(),"paid treatment",16).toUpperCase(Locale.ROOT)).requiresBalance(Boolean.TRUE.equals(r.getRequiresBalance())?1:0).requiresAttachment(Boolean.TRUE.equals(r.getRequiresAttachment())?1:0).active(Boolean.FALSE.equals(r.getActive())?0:1).description(r.getDescription()).createdBy(a.id()).updatedBy(a.id()).build();need(Set.of("DAY","HALF_DAY","HOUR").contains(t.getUnit())&&Set.of("PAID","UNPAID").contains(t.getPaidTreatment()),"Invalid leave type semantics");if(id==null)need(mapper.insertLeaveType(t)==1,"Leave type creation failed");else need(mapper.updateLeaveType(t)==1,"Leave type not found");audit(a.id(),null,id==null?"LEAVE_TYPE_CREATED":"LEAVE_TYPE_UPDATED",t.getCode());return mapper.leaveType(t.getId());}
 public PageResult<LeaveType> types(Integer page,Integer size){access.actor();var w=pagination.window(page,size,true);var rows=pagination.limit(w)==0?List.<LeaveType>of():mapper.leaveTypes(w.offset(),pagination.limit(w));return pagination.result(w,rows,mapper.leaveTypeCount());}
 @Transactional(isolation=Isolation.READ_COMMITTED) public LeaveAllocation allocate(WorkforceRequests.AllocationCreate r){var a=access.actor();access.hrOrSystem(a);need(r!=null&&r.getEmployeeId()!=null&&r.getLeaveTypeId()!=null,"Employee and leave type are required");String key=text(r.getRequestKey(),"request key",100);var old=mapper.allocationByKey(a.id(),key);if(old!=null)return old;access.employee(r.getEmployeeId());need(mapper.leaveType(r.getLeaveTypeId())!=null,"Leave type not found");need(r.getPeriodStart()!=null&&r.getPeriodEnd()!=null&&!r.getPeriodEnd().isBefore(r.getPeriodStart()),"Allocation period is invalid");need(r.getAmount()!=null&&r.getAmount().signum()>0&&r.getAmount().scale()<=2,"Allocation amount is invalid");var allocation=LeaveAllocation.builder().employeeId(r.getEmployeeId()).leaveTypeId(r.getLeaveTypeId()).periodStart(r.getPeriodStart()).periodEnd(r.getPeriodEnd()).amount(r.getAmount()).reason(text(r.getReason(),"reason",500)).requestKey(key).createdBy(a.id()).build();need(mapper.insertAllocation(allocation)==1,"Allocation creation failed");audit(a.id(),r.getEmployeeId(),"LEAVE_ALLOCATION_ADDED","Allocation "+allocation.getId());return allocation;}
 public LeaveBalance balance(Long typeId,LocalDate periodStart,LocalDate periodEnd){var a=access.actor();return balance(a.id(),typeId,periodStart,periodEnd);}
 public LeaveBalance balance(Long employee,Long typeId,LocalDate start,LocalDate end){var a=access.actor();if(!a.id().equals(employee))access.hrOrSystem(a);need(start!=null&&end!=null&&!end.isBefore(start),"Balance period is invalid");BigDecimal allocated=zero(mapper.allocated(employee,typeId,start,end)),pending=zero(mapper.leaveAmount(employee,typeId,1,start.atStartOfDay(),end.plusDays(1).atStartOfDay())),approved=zero(mapper.leaveAmount(employee,typeId,2,start.atStartOfDay(),end.plusDays(1).atStartOfDay()));return LeaveBalance.builder().employeeId(employee).leaveTypeId(typeId).allocated(allocated).pending(pending).approved(approved).available(allocated.subtract(pending).subtract(approved)).build();}
 private BigDecimal zero(BigDecimal v){return v==null?BigDecimal.ZERO:v;}
 @Transactional public LeaveRequest create(WorkforceRequests.LeaveCreate input){var a=access.actor();need(!a.has("OWNER"),"LEAVE_EXEMPT: OWNER accounts do not participate in employee leave");need(input!=null,"Request required");String key=text(input.getRequestKey(),"request key",100);var old=mapper.leaveByKey(a.id(),key);if(old!=null)return old;var r=LeaveRequest.builder().employeeId(a.id()).leaveTypeId(input.getLeaveTypeId()).startAt(input.getStartAt()).endAt(input.getEndAt()).requestedAmount(input.getRequestedAmount()).reason(text(input.getReason(),"reason",500)).attachmentReference(input.getAttachmentReference()).requestKey(key).status(0).build();validate(r,mapper.leaveType(r.getLeaveTypeId()));try{need(mapper.insertLeave(r)==1,"Leave draft creation failed");}catch(DuplicateKeyException e){return mapper.leaveByKey(a.id(),key);}history(r.getId(),"DRAFT_CREATED",a.id(),null);audit(a.id(),a.id(),"LEAVE_DRAFT_CREATED","Leave "+r.getId());return mapper.leave(r.getId());}
 @Transactional public LeaveRequest update(Long id,WorkforceRequests.LeaveCreate input){var a=access.actor();var current=mapper.lockLeave(id);need(current!=null&&current.getEmployeeId().equals(a.id())&&current.getStatus()==0,"Only an owned draft can be edited");var r=LeaveRequest.builder().id(id).employeeId(a.id()).leaveTypeId(input.getLeaveTypeId()).startAt(input.getStartAt()).endAt(input.getEndAt()).requestedAmount(input.getRequestedAmount()).reason(text(input.getReason(),"reason",500)).attachmentReference(input.getAttachmentReference()).build();validate(r,mapper.leaveType(r.getLeaveTypeId()));need(mapper.updateDraft(r)==1,"Leave draft changed concurrently");history(id,"DRAFT_UPDATED",a.id(),null);return mapper.leave(id);}
 @Transactional(isolation=Isolation.READ_COMMITTED) public LeaveRequest submit(Long id){var a=access.actor();need(!a.has("OWNER"),"LEAVE_EXEMPT: OWNER accounts do not participate in employee leave");mapper.lockUser(a.id());var r=mapper.lockLeave(id);need(r!=null&&r.getEmployeeId().equals(a.id()),"Leave request not found");if(r.getStatus()==1)return r;need(r.getStatus()==0,"Only a draft can be submitted");var t=mapper.lockLeaveType(r.getLeaveTypeId());validate(r,t);need(mapper.overlap(a.id(),id,r.getStartAt(),r.getEndAt())==0,"Leave overlaps a pending or approved request");var route=routing.resolve(a);routing.requireNotExempt(route,"LEAVE");if(Integer.valueOf(1).equals(t.getRequiresBalance())){var start=r.getStartAt().toLocalDate();var end=r.getEndAt().toLocalDate();BigDecimal allocated=zero(mapper.allocated(a.id(),t.getId(),start,end));LocalDate periodStart=mapper.allocationStart(a.id(),t.getId(),start,end),periodEnd=mapper.allocationEnd(a.id(),t.getId(),start,end);need(periodStart!=null&&periodEnd!=null,"No leave allocation covers the request");BigDecimal pending=zero(mapper.leaveAmount(a.id(),t.getId(),1,periodStart.atStartOfDay(),periodEnd.plusDays(1).atStartOfDay())),approved=zero(mapper.leaveAmount(a.id(),t.getId(),2,periodStart.atStartOfDay(),periodEnd.plusDays(1).atStartOfDay()));need(allocated.subtract(pending).subtract(approved).compareTo(r.getRequestedAmount())>=0,"Insufficient leave balance");}Long task=workflows.create(7,"LEAVE_REQUEST:"+id,"Leave request "+id,r.getReason(),a.id(),route);need(mapper.submitLeave(id,route.departmentId(),route.approver(),route.code(),task,now())==1,"Leave changed concurrently");history(id,"APPROVAL_ROUTE_RESOLVED",a.id(),route.code());audit(a.id(),a.id(),"LEAVE_SUBMITTED","Leave "+id+" route "+route.code());return mapper.leave(id);}
 @Transactional(isolation=Isolation.READ_COMMITTED) public LeaveRequest decide(Long id,boolean approve,String note){var a=access.actor();var r=mapper.lockLeave(id);if(r==null)throw new BusinessException(404,"Leave request not found");if(r.getStatus()!=1)return r;if(!Objects.equals(r.getApproverUserIdSnapshot(),a.id())||r.getEmployeeId().equals(a.id()))throw access.denied();mapper.lockUser(r.getEmployeeId());if(approve){need(mapper.overlap(r.getEmployeeId(),r.getId(),r.getStartAt(),r.getEndAt())==0,"Leave now overlaps another request");}else need(note!=null&&!note.isBlank(),"Rejection note is required");need(mapper.decideLeave(id,approve?2:3,note,a.id(),now())==1,"Leave changed concurrently");workflows.finish(r.getTaskId(),a.id(),!approve,approve?"Leave approved":"Leave rejected");history(id,approve?"APPROVED":"REJECTED",a.id(),note);audit(a.id(),r.getEmployeeId(),approve?"LEAVE_APPROVED":"LEAVE_REJECTED","Leave "+id);return mapper.leave(id);}
 @Transactional public LeaveRequest claim(Long id){var a=access.actor();var r=mapper.lockLeave(id);need(r!=null&&r.getStatus()==1&&r.getApproverUserIdSnapshot()==null,"Leave request is not claimable");need(!r.getEmployeeId().equals(a.id()),"Self approval is forbidden");workflows.claim(r.getTaskId(),a);need(mapper.resolveLeaveApprover(r.getTaskId(),a.id())==1,"Approver changed concurrently");history(id,"APPROVER_RESOLVED",a.id(),r.getApprovalRoute());audit(a.id(),r.getEmployeeId(),"LEAVE_APPROVER_RESOLVED","Leave "+id);return mapper.leave(id);}
 @Transactional public LeaveRequest cancel(Long id,String reason){var a=access.actor();var r=mapper.lockLeave(id);if(r==null||!r.getEmployeeId().equals(a.id()))throw new BusinessException(404,"Leave request not found");if(r.getStatus()==4)return r;need(Set.of(0,1,2).contains(r.getStatus()),"Leave cannot be cancelled");if(r.getStatus()==2)need(now().isBefore(r.getStartAt()),"Started approved leave cannot be cancelled by employee");need(mapper.cancelLeave(id,a.id(),r.getStatus(),text(reason,"cancel reason",500),now())==1,"Leave changed concurrently");if(r.getStatus()==1)workflows.finish(r.getTaskId(),a.id(),true,"Leave cancelled by employee");history(id,"CANCELLED",a.id(),reason);audit(a.id(),a.id(),"LEAVE_CANCELLED","Leave "+id);return mapper.leave(id);}
 public LeaveRequest detail(Long id){var a=access.actor();var r=mapper.leave(id);if(r==null)throw new BusinessException(404,"Leave request not found");if(!r.getEmployeeId().equals(a.id())&&!Objects.equals(r.getApproverUserIdSnapshot(),a.id())&&!a.any("HR_ADMIN","OWNER","SUPER_ADMIN"))throw access.denied();return r;}
 public PageResult<LeaveRequest> mine(Integer status,Integer page,Integer size){var a=access.actor();return page(a.id(),null,status,page,size);}
 public PageResult<LeaveRequest> pending(Integer page,Integer size){var a=access.actor();var w=pagination.window(page,size,true);var rows=pagination.limit(w)==0?List.<LeaveRequest>of():mapper.pendingLeaves(a.id(),w.offset(),pagination.limit(w));return pagination.result(w,rows,mapper.pendingLeaveCount(a.id()));}
 public PageResult<LeaveRequest> query(Long employee,Integer status,Integer page,Integer size){var a=access.actor();access.hrOrSystem(a);return page(employee,null,status,page,size);}
 @Transactional public LeaveRequest reassign(Long id,Long approver,String reason){var a=access.actor();access.system(a);var r=mapper.lockLeave(id);need(r!=null&&r.getStatus()==1,"Leave request is not pending");var requester=access.employee(r.getEmployeeId());var route=routing.resolve(requester);routing.requireNotExempt(route,"LEAVE");need(!Objects.equals(r.getEmployeeId(),approver),"Self approval is forbidden");if(route.approver()!=null)need(Objects.equals(route.approver(),approver),"Recovery approver must match current routing");else need(route.eligibleRoles().stream().anyMatch(access.employee(approver).roles()::contains),"Recovery approver is not eligible for current routing");access.employee(approver);need(mapper.reassignLeave(id,approver)==1,"Leave changed concurrently");workflows.reassign(r.getTaskId(),approver,a.id(),text(reason,"reassignment reason",500));history(id,"APPROVER_REROUTED",a.id(),reason+" via "+route.code());audit(a.id(),r.getEmployeeId(),"LEAVE_APPROVER_REROUTED","Leave "+id);return mapper.leave(id);}
 private PageResult<LeaveRequest> page(Long employee,Long approver,Integer status,Integer page,Integer size){var w=pagination.window(page,size,true);var rows=pagination.limit(w)==0?List.<LeaveRequest>of():mapper.leavePage(employee,approver,status,w.offset(),pagination.limit(w));return pagination.result(w,rows,mapper.leaveCount(employee,approver,status));}
}
